steps.code:
# Let's examine tasks in both Trip Planning projects to find which one is for Bangkok.
import json
for pid in [280, 281]:
    data = apis.todoist.show_tasks(project_id=pid, access_token=access_token)
    print(f"Project {pid}:")
    for t in data.get("no_section_tasks", []):
        print(f"  {t['task_id']}: {t['title']}")
    for sec in data.get("section_tasks", []):
        for t in sec.get("tasks", []):
            print(f"  {t['task_id']}: {t['title']} (section {sec.get('section_id')})")
    print()

